//
// Fluxo de login pela UI. A API é totalmente stubada (ver cypress/support/commands.ts):
// nenhum teste aqui depende do backend.

describe('Login', () => {
  const credenciais = { email: 'maria@teste.com', senha: 'senha-correta' }

  beforeEach(() => {
    // Primeiro o bloqueio: o stub definido por último tem prioridade sobre o anterior.
    cy.bloquearApi()
    cy.stubLogin(credenciais)
    cy.visit('/login')
  })

  it('envia o formulário vazio → mostra os erros de validação e não chama a API', () => {
    cy.get('[data-cy="login-submit"]').click()

    cy.contains('Informe seu e-mail').should('be.visible')
    cy.contains('Informe sua senha').should('be.visible')
    cy.get('@login.all').should('have.length', 0)
    cy.location('pathname').should('eq', '/login')
  })

  it('informa e-mail inválido → mostra o erro de formato e não chama a API', () => {
    cy.get('[data-cy="login-email"]').type('isso-nao-e-email')
    cy.get('[data-cy="login-senha"]').type('qualquer-senha')
    cy.get('[data-cy="login-submit"]').click()

    cy.contains('Informe um e-mail válido').should('be.visible')
    cy.get('@login.all').should('have.length', 0)
  })

  it('informa credenciais erradas → mostra a mensagem da API e permanece no login', () => {
    cy.get('[data-cy="login-email"]').type(credenciais.email)
    cy.get('[data-cy="login-senha"]').type('senha-errada')
    cy.get('[data-cy="login-submit"]').click()

    cy.wait('@login').its('response.statusCode').should('eq', 401)
    cy.get('[data-cy="login-erro"]').should('have.text', 'E-mail ou senha inválidos.')
    cy.location('pathname').should('eq', '/login')
  })

  it('informa credenciais corretas → envia o payload certo e vai para o painel', () => {
    cy.get('[data-cy="login-email"]').type(credenciais.email)
    cy.get('[data-cy="login-senha"]').type(credenciais.senha)
    cy.get('[data-cy="login-submit"]').click()

    cy.wait('@login').its('request.body').should('deep.equal', credenciais)
    // Depois do login a store recarrega a sessão via /auth/me.
    cy.wait('@me')
    cy.location('pathname').should('eq', '/')
  })
})
